using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new()
        {
            Name = "McpHttpServer",
            Version = "1.0.0"
        };
    })
    .WithHttpTransport()
    .WithTools<MyTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

// --- Tools ---

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "echo", Title = "Echo")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add", Title = "Add Numbers")]
    public static string Add(double a, double b) => $"Result: {a + b}";
}

// --- Resources ---

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app-settings",
        Title = "Application Settings", MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            environment = "production",
            maxRetries = 3,
            timeoutSeconds = 30,
            features = new { darkMode = true, betaAccess = false }
        };
        return System.Text.Json.JsonSerializer.Serialize(settings);
    }

    [McpServerResource(UriTemplate = "config://app/version", Name = "app-version",
        Title = "Application Version", MimeType = "text/plain")]
    public static string GetAppVersion() => "1.0.0-release";
}

